mod common;

use std::time::{Duration, Instant};

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig, TscClientError};

// Q1: cancel Client::request mid-body-write against the repo's own `echo` fake.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cancelled_request_desyncs_session() {
    let (_dir, config) = common::spawn_fake("echo");
    let supervisor = Supervisor::spawn(config).await.expect("spawn");
    let client = supervisor.client();
    let other = client.clone();

    // Baseline: session works.
    let ok = other.request("ping", serde_json::json!({"n": 0}), Duration::from_secs(2)).await;
    eprintln!("baseline: {:?}", ok.as_ref().map(|r| r.value.clone()));
    assert!(ok.is_ok());

    let big = "x".repeat(8 * 1024 * 1024);
    let mut fut = Box::pin(client.request("big", serde_json::json!({"blob": big}), Duration::from_secs(5)));
    let cancelled = tokio::select! {
        biased;
        r = &mut fut => { eprintln!("big completed on first poll: {:?}", r.is_ok()); false }
        () = std::future::ready(()) => true,
    };
    drop(fut); // caller cancellation, e.g. an outer select!/timeout
    eprintln!("cancelled mid-write: {cancelled}");
    assert!(cancelled);

    for n in 1..=3 {
        let t = Instant::now();
        let r = other.request("ping", serde_json::json!({"n": n}), Duration::from_millis(500)).await;
        eprintln!("after-cancel ping {n}: {:?} in {:?}", r.as_ref().map(|x| x.value.clone()).map_err(|e| format!("{e:?}")), t.elapsed());
        assert!(matches!(r, Err(TscClientError::Timeout { .. })));
    }
    eprintln!("is_alive after desync: {}", supervisor.is_alive());
    drop(client);
    drop(other);
    supervisor.shutdown().await.expect("shutdown");
}

fn non_reading_child(dir: &tempfile::TempDir) -> SupervisorConfig {
    let ts = dir.path().join("node_modules").join("typescript");
    let bin = ts.join("bin");
    std::fs::create_dir_all(&bin).unwrap();
    std::fs::write(ts.join("package.json"), r#"{"version": "7.1.0-test"}"#).unwrap();
    let tsc = bin.join("tsc");
    // Alive, never reads stdin: models a wedged child.
    std::fs::write(&tsc, "#!/bin/sh\nexec sleep 30\n").unwrap();
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(&tsc, std::fs::Permissions::from_mode(0o755)).unwrap();
    SupervisorConfig::new(
        Utf8PathBuf::from_path_buf(tsc).unwrap(),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap(),
        &["7.1.0-test"],
    )
}

// Q2a: large request to a non-reading child blocks past its deadline and starves a clone.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn write_ignores_deadline_and_blocks_clones() {
    let dir = tempfile::tempdir().unwrap();
    let mut supervisor = Supervisor::spawn(non_reading_child(&dir)).await.expect("spawn");
    let clone = supervisor.client();

    let small = tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(50)).await;
        let t = Instant::now();
        let r = tokio::time::timeout(
            Duration::from_secs(2),
            clone.request("small", serde_json::json!({}), Duration::from_millis(100)),
        )
        .await;
        (r.is_err(), t.elapsed())
    });

    let big = "x".repeat(1024 * 1024);
    let t = Instant::now();
    let r = tokio::time::timeout(
        Duration::from_secs(2),
        supervisor.request("big", serde_json::json!({"blob": big}), Duration::from_millis(100)),
    )
    .await;
    eprintln!("big (deadline 100ms): outer-timeout-hit={} after {:?}", r.is_err(), t.elapsed());
    let (small_outer_hit, small_elapsed) = small.await.unwrap();
    eprintln!("clone small (deadline 100ms): outer-timeout-hit={small_outer_hit} after {small_elapsed:?}");
    assert!(r.is_err());
    assert!(small_outer_hit);
    supervisor.shutdown().await.expect("shutdown");
}

// Q2b: small requests only; timed-out requests accumulate in the pipe until a write blocks forever.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn small_timed_out_requests_eventually_block_past_deadline() {
    let dir = tempfile::tempdir().unwrap();
    let mut supervisor = Supervisor::spawn(non_reading_child(&dir)).await.expect("spawn");
    let payload = "y".repeat(4096);
    for i in 0..200 {
        let t = Instant::now();
        let r = tokio::time::timeout(
            Duration::from_secs(2),
            supervisor.request("q", serde_json::json!({"p": payload}), Duration::from_millis(20)),
        )
        .await;
        match r {
            Ok(Err(TscClientError::Timeout { .. })) => {}
            Ok(other) => panic!("request {i}: unexpected {other:?}"),
            Err(_) => {
                eprintln!("request {i} (4 KiB, deadline 20ms) still blocked after {:?}; {} prior requests timed out normally", t.elapsed(), i);
                supervisor.shutdown().await.expect("shutdown");
                return;
            }
        }
    }
    panic!("never blocked");
}

